import {useTranslation} from 'react-i18next';
import {
  Content,
  INotification,
  ParamEntry,
} from '../../../../model/interface/notification.interface';
import React from 'react';
import RenderHtml from 'react-native-render-html';
import {stylesHTML} from './helper';
import {TouchableOpacity, View} from 'react-native';
import TextCM from '../../../components/Text';
import styles from './styles';
import {Font, NavigationName} from '../../../../constants';
import {Badge, Divider} from 'react-native-paper';
import {Icon} from '@ui-kitten/components';
import {isEmpty} from 'lodash';
import {useNotificationServices} from '../../../../hooks/useNotificationServices';
import Toast from 'react-native-toast-message';
import {useETaskZutandStore} from '../../../../zutand/eTaskZutandStore';
import {useAppSelector} from '../../../../hooks/useRedux';
import {useNavigation} from '@react-navigation/native';
interface NotificationProps {
  notiItem: INotification;
  tab: 'read' | 'unread';
}

export default function NotificationCard({notiItem, tab}: NotificationProps) {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const NotificationService = useNotificationServices();
  const {totalNotify, listNotify, setTotalNotify, setListNotify} =
    useETaskZutandStore();
  const dataAccount = useAppSelector(state => state.account.dataAccount);

  const stripHtml = (html: string): string => {
    if (!html) return '';
    return html.replace(/<[^>]*>?/gm, '');
  };
  const getAttrKey = (
    paramEntry: Record<string, any> | null | undefined,
  ): string | undefined => {
    if (
      paramEntry &&
      typeof paramEntry === 'object' &&
      Object.keys(paramEntry).length > 0
    ) {
      const key = Object.keys(paramEntry)[0];
      return key;
    }
    return undefined;
  };

  const getAttr = (key: string): string => {
    if (key === 'name') {
      return 'board.name';
    } else if (key === 'priority') {
      return 'task.priority';
    } else if (key === 'tags') {
      return 'task.tag';
    } else if (key === 'startDate') {
      return 'task.start-date';
    } else if (key === 'dueDate') {
      return 'task.due-date';
    } else if (key === 'description') {
      return 'task.description';
    } else if (key === 'remindDate') {
      return 'Thời gian nhắc nhở';
    } else if (key === 'status') {
      return 'task.status';
    } else if (key === 'rating') {
      return 'task.rate';
    } else if (key === 'rateDetails') {
      return 'task.rateComment';
    }

    return '';
  };

  const getAuthority = (name: string): string => {
    if (name === 'all') {
      return 'NT.selectAuth.all';
    } else if (name === 'comment') {
      return 'NT.selectAuth.comment';
    } else if (name === 'read') {
      return 'NT.selectAuth.read';
    } else if (name === 'edit') {
      return 'NT.selectAuth.edit';
    }
    return '';
  };

  const notiContent = notiItem.content as Content;
  const isTask = !!notiContent.taskDto;
  let key = getAttrKey(
    isTask
      ? notiContent.taskDto?.paramEntry
      : notiContent.listTaskDTO?.paramEntry,
  );
  let oldValueTrans: string = '';
  let newValueTrans: string = '';
  const paramEntrySource: ParamEntry | null = isTask
    ? notiContent?.taskDto?.paramEntry
    : notiContent?.listTaskDTO?.paramEntry;
  let oldValue: any = undefined;
  let newValue: any = undefined;
  if (key !== undefined && paramEntrySource) {
    const entryData = paramEntrySource[key];
    oldValue = entryData?.old;
    newValue = entryData?.new;
  }
  if (isTask && notiContent.taskDto?.param) {
    const params = JSON.parse(notiContent.taskDto?.param || '');
    if (params.newStatusType === 'custom') {
      newValue = params.newStatus;
    } else {
      newValueTrans = 'board.status-' + params.newStatus;
    }
    if (params.oldStatusType === 'custom') {
      oldValue = params.oldStatus;
    } else {
      oldValueTrans = 'board.status-' + params.oldStatus;
    }
  }

  const iconName =
    notiContent.createdBy !== 'system' ? 'people-outline' : 'settings-outline';
  const handleDirect = (notiItem: INotification) => {
    if (notiContent?.parentTaskDto && notiContent?.taskDto) {
      navigation.navigate(NavigationName.TaskDetailScreen, {
        taskId: notiContent.taskDto.id,
        type: 'subTask',
        isFromNoti: true,
      });
      return;
    } else if (notiContent?.taskDto) {
      navigation.navigate(NavigationName.TaskDetailScreen, {
        taskId: notiContent.taskDto.id,
        type: 'task',
        isFromNoti: true,
      });
      return;
    }

    if (
      [
        'ASSIGNEE_UPDATE_TASK_STATUS_IN_MY_LIST',
        'ASSIGN_USER_AS_COORDINATOR_OWNER',
        'REMOVE_TASK_LIST_COORDINATOR_OWNER',
      ].includes(notiItem.type) ||
      ([
        'LIST_OWNER_INFO_UPDATED',
        'LIST_OWNER_DELETED',
        'LIST_OWNER_ADD_INFO',
        'USER_EDITED_LIST_INFO',
        'USER_DELETED_LIST',
        'USER_ADD_INFO_TO_LIST',
        'TASK_PERMISSION_UPDATED',
        'TASK_PERMISSION_DELETED',
        'TASK_PERMISSION_ADD_INFO',
        'COORDINATOR_ADDED_NEW_TASK',
        'COORDINATOR_UPDATED_TASK_INFO',
        'TEMPLATE_PERMISSION_EDITED',
        'TEMPLATE_PERMISSION_DELETED',
        'TEMPLATE_PERMISSION_ADD_INFO',
      ].includes(notiItem.type) &&
        dataAccount.email === notiItem.createdBy) ||
      (notiItem.type === 'NOTIFY_COMMENT' &&
        notiContent?.commentNotifyDto?.users?.[0]?.role === 'owner')
    ) {
      navigation.navigate(NavigationName.TaskScreen, {
        taskId: notiContent.taskDto.id,
      });
    } else if (
      [
        'APPROVE_ASSIGN',
        'ASSIGN_USER_AS_TASK_APPROVED',
        'TASK_NEEDS_APPROVED',
        'TASK_PENDING_APPROVED',
      ].includes(notiItem.type) ||
      (notiItem.type === 'NOTIFY_COMMENT' &&
        notiContent?.commentNotifyDto?.users?.[0]?.role === 'approver')
    ) {
      navigation.navigate(NavigationName.TaskScreen, {
        taskId: notiContent.taskDto.id,
      });
    } else if (
      [
        'TASK_RATING_ADD',
        'TASK_RATING_UPDATED',
        'TASK_COMMENT_ADD',
        'TASK_COMMENT_UPDATED',
        'ASSIGN_TASK_LIST_TO_USER',
        'ASSIGN_TASK_LIST_TO_GROUP',
        'ASSIGN_TASK_LIST_TO_ORG',
        'ASSIGN_TASK_TO_USER',
        'ASSIGN_TASK_TO_GROUP',
        'ASSIGN_TASK_TO_ORG',
        'ASSIGN_SUBTASK_TO_USER',
        'ASSIGN_SUBTASK_TO_GROUP',
        'ASSIGN_SUBTASK_TO_ORG',
        'TASK_REMINDER',
        'TASK_REMINDER_NO_DATE',
        'TASK_OVERDUE_REMINDER',
        'TASK_APPROVED',
      ].includes(notiItem.type) ||
      ([
        'LIST_OWNER_INFO_UPDATED',
        'LIST_OWNER_DELETED',
        'LIST_OWNER_ADD_INFO',
        'USER_EDITED_LIST_INFO',
        'USER_DELETED_LIST',
        'USER_ADD_INFO_TO_LIST',
        'LIST_OWNER_UPDATED_TASK_INFO',
        'LIST_OWNER_DELETED_TASK',
        'TASK_OWNER_ADD_INFO',
        'TASK_PERMISSION_UPDATED',
        'TASK_PERMISSION_DELETED',
        'TASK_PERMISSION_ADD_INFO',
        'COORDINATOR_ADDED_NEW_TASK',
        'COORDINATOR_UPDATED_TASK_INFO',
        'TEMPLATE_OWNER_UPDATED',
        'TEMPLATE_OWNER_DELETED',
        'TEMPLATE_OWNER_ADD_INFO',
        'TEMPLATE_PERMISSION_EDITED',
        'TEMPLATE_PERMISSION_DELETED',
        'TEMPLATE_PERMISSION_ADD_INFO',
      ].includes(notiItem.type) &&
        (notiContent?.assignGroupDto ||
          notiContent?.assignOrgDto ||
          notiContent?.assignTaskDto)) ||
      (notiItem.type === 'NOTIFY_COMMENT' &&
        notiContent?.commentNotifyDto?.users?.[0]?.role === 'assign')
    ) {
      navigation.navigate(NavigationName.TaskScreen, {
        taskId: notiContent.taskDto.id,
      });
    } else if (
      [
        'SHARE_TASK_LIST_TO_USER',
        'SHARE_TASK_LIST_TO_GROUP',
        'SHARE_TASK_LIST_TO_ORG',
        'SHARE_TASK_TO_USER',
        'SHARE_TASK_TO_GROUP',
        'SHARE_TASK_TO_ORG',
      ].includes(notiItem.type) ||
      ([
        'LIST_OWNER_INFO_UPDATED',
        'LIST_OWNER_DELETED',
        'LIST_OWNER_ADD_INFO',
        'USER_EDITED_LIST_INFO',
        'USER_DELETED_LIST',
        'USER_ADD_INFO_TO_LIST',
        'LIST_OWNER_UPDATED_TASK_INFO',
        'LIST_OWNER_DELETED_TASK',
        'TASK_OWNER_ADD_INFO',
        'TASK_PERMISSION_UPDATED',
        'TASK_PERMISSION_DELETED',
        'TASK_PERMISSION_ADD_INFO',
        'COORDINATOR_ADDED_NEW_TASK',
        'COORDINATOR_UPDATED_TASK_INFO',
        'TEMPLATE_OWNER_UPDATED',
        'TEMPLATE_OWNER_DELETED',
        'TEMPLATE_OWNER_ADD_INFO',
        'TEMPLATE_PERMISSION_EDITED',
        'TEMPLATE_PERMISSION_DELETED',
        'TEMPLATE_PERMISSION_ADD_INFO',
      ].includes(notiItem.type) &&
        notiContent?.taskShareInternal) ||
      (notiItem.type === 'NOTIFY_COMMENT' &&
        notiContent?.commentNotifyDto?.users?.[0]?.role === 'share')
    ) {
    } else if (
      [
        'SHARE_TEMPALTE_TASK_LIST_TO_USER',
        'SHARE_TEMPALTE_TASK_LIST_TO_GROUP',
        'SHARE_TEMPALTE_TASK_LIST_TO_ORG',
      ].includes(notiItem.type)
    ) {
      navigation.navigate(NavigationName.TaskScreen, {
        taskId: notiContent.taskDto.id,
      });
    } else if (
      ['ASSIGN_USER_AS_COORDINATOR', 'REMOVE_TASK_LIST_COORDINATOR'].includes(
        notiItem.type,
      )
    ) {
      // navigation.navigate(NavigationName.TaskScreen, {
      //   taskId: notiContent.taskDto.id,
      // });
    }
    return;
  };
  const markAsReaded = async (notiItem: INotification) => {
    try {
      let data = await NotificationService.markAsReadNotify(notiItem.id);
      if (data !== 'ok') {
        Toast.show({
          type: 'error',
          text1: t('CM.error'),
        });
        return;
      }
      const rmedListNoti = listNotify.filter(no => no.id !== notiItem.id);
      setListNotify(rmedListNoti);
      setTotalNotify(totalNotify - 1);
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('cm.noti'),
        text2: 'Có lỗi xảy ra',
      });
    }
  };
  const handelPressNoti = (notiItem: INotification) => {
    if (notiItem.status === 'unread') {
      markAsReaded(notiItem);
    }
    if (
      [
        'USER_DELETED_LIST',
        'LIST_OWNER_DELETED',
        'LIST_OWNER_DELETED_TASK',
        'TASK_PERMISSION_DELETED',
        'TEMPLATE_OWNER_DELETED',
        'REMOVE_TASK_LIST_COORDINATOR',
        'REMOVE_TASK_LIST_COORDINATOR_OWNER',
      ].includes(notiItem.type)
    ) {
      return;
    } else if (notiItem.type === '8-3-EVENTS') {
      // window.open('https://hellokittty123.github.io/8-3-KYTA/', '_blank');
    }
    handleDirect(notiItem);
  };
  const convertTime = (isoString: string) => {
    const date = new Date(isoString);
    const day = ('0' + date.getDate()).slice(-2);
    const month = ('0' + (date.getMonth() + 1)).slice(-2);
    const year = date.getFullYear();
    const hours = ('0' + date.getHours()).slice(-2);
    const minutes = ('0' + date.getMinutes()).slice(-2);
    return `${day}/${month}/${year} ${hours}:${minutes}`;
  };

  return (
    <TouchableOpacity
      style={styles.ctnMain}
      onPress={() => handelPressNoti(notiItem)}>
      <View style={styles.ctnIcon}>
        <Icon width={20} height={20} fill={'#39ac6c'} name={iconName} />
        {tab === 'unread' && <Badge size={10} style={styles.badge}></Badge>}
      </View>
      <View style={{flex: 1, rowGap: 10}}>
        <RenderHtml
          source={{
            html: t(`NT.${notiItem.type}`, {
              id: notiItem.id,
              message: `navbar.notify.${notiItem.type}`,
              name: notiContent?.taskDto?.name,
              taskName: notiContent?.parentTaskDto?.name,
              listTaskName: notiContent?.listTaskDTO?.name,
              createdBy: notiContent.createdBy,
              createdDate: notiContent.createdDateNotify?.toString(),
              aclName: !isEmpty(
                getAuthority(notiContent?.taskShareInternal?.aclName),
              )
                ? t(getAuthority(notiContent?.taskShareInternal?.aclName))
                : '',
              aclNameKey: notiContent?.taskShareInternal?.aclName,
              orgName: notiContent?.assignOrgDto?.orgName,
              groupName:
                notiContent?.assignGroupDto?.groupName ||
                notiContent?.taskShareInternal?.groupName,
              attr:
                !isEmpty(getAttr(key || '')) && t(`NT.${getAttr(key || '')}`),
              oldValue: oldValue
                ? stripHtml(oldValue)
                : oldValueTrans && t(`NT.${oldValueTrans}`),
              newValue: newValue
                ? stripHtml(newValue)
                : newValueTrans && t(`NT.${newValueTrans}`),
              coordinator: notiContent?.assignTaskDto?.assignName,
              rating: notiContent?.taskDto?.rating,
              type: notiItem.type,
              dueDate: notiContent?.taskDto?.dueDate,
              status: notiItem.status,
              style: stylesHTML.RED_BOLD,
            }),
          }}
        />
        <TextCM
          style={[
            {
              fontFamily: Font.InterRegular400,
            },
            styles.text,
          ]}>
          {convertTime(notiContent.createdDateNotify)}
        </TextCM>
        <Divider />
      </View>
    </TouchableOpacity>
  );
}
