import {useState} from 'react';
import {useUserStore} from '../../../../../../../zutand/user-store';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Image, Pressable, ScrollView, View} from 'react-native';
import {IUser} from '../../../../../../../model/interface/account.interface';
import {String} from '../../../../../../../constants';
import TextCM from '../../../../../../components/Text';
import {Divider, Icon} from '@ui-kitten/components';
import ButtonCM from '../../../../../../components/Button';
import {ICheckListItem} from '../../../../helper';

type Props = {
  onClose?: () => void;
  listUserInTask?: IUser[];
  handleAssignCheckList?: (data: any) => void;
  type: 'T' | 'L' | 'C';
  valueCheckList?: ICheckListItem;
};

const AssignCheckList = ({
  onClose,
  listUserInTask,
  handleAssignCheckList,
  type,
  valueCheckList,
}: Props) => {
  const {listUser} = useUserStore();
  const [selectUser, setSelectUser] = useState<IUser>(
    listUser?.find(
      u => u.resourceId === valueCheckList?.assign?.[0]?.userId,
    ) as IUser,
  );

  const handleSubmit = () => {
    if (selectUser?.resourceId === valueCheckList?.assign?.[0]?.userId) {
      onClose?.();
      return;
    }
    const data = {
      id: new Date().getTime().toString(),
      orgIn: selectUser?.orgIn,
      custId: selectUser?.custId,
      userId: selectUser?.resourceId,
      type: type,
    };
    handleAssignCheckList?.({
      ...valueCheckList,
      assign: [data],
    });
    onClose?.();
  };

  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#00204D',
        }}
        fillIconBackLeft="#00204DB2"
        contentStyle={{
          backgroundColor: '#fff',
        }}
        title={''}
        onPressIconLeft={onClose}
      />

      <Divider />

      <ScrollView
        style={{
          padding: 10,
        }}>
        {listUserInTask?.map((item, idx) => (
          <Pressable
            onPress={() => setSelectUser(item)}
            key={idx}
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: 16,
            }}>
            <View
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                columnGap: 8,
              }}>
              <Image
                style={{
                  width: 32,
                  height: 32,
                  borderRadius: 16,
                }}
                source={{uri: item.imageUrl || String.DEFAULT_IMAGE}}
              />
              <View>
                <TextCM>{item.personalName}</TextCM>
                <TextCM>{item.email}</TextCM>
              </View>
            </View>

            {selectUser?.resourceId === item.resourceId && (
              <Icon name="checkmark" width={24} height={24} />
            )}
          </Pressable>
        ))}
      </ScrollView>

      <View
        style={{
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'center',
          columnGap: 10,
          paddingHorizontal: 16,
        }}>
        <ButtonCM style={{flex: 1}} label="Huỷ" onPress={() => onClose?.()} />
        <ButtonCM style={{flex: 1}} label="Lưu" onPress={handleSubmit} />
      </View>
    </>
  );
};

export default AssignCheckList;
