import React, {useState} from 'react';
import {View, TouchableOpacity} from 'react-native';
import TextCM from '../../../../../../components/Text';
import TableCM from '../../../../../../components/Table';
import styles from './styles';
import DownAngle from '../../../../../../../assets/images/ic/down_angle.svg';
import RightAngle from '../../../../../../../assets/images/ic/right_angle.svg';
import {Font} from '../../../../../../../constants';
type TableItem = {
  [key: string]: string | number | JSX.Element;
};

type TableGroup = {
  status: string;
  tableData: TableItem[];
};

type Props = {
  tableDataGroup: TableGroup[];
};

const STATUS_NAMES: Record<string, string> = {
  todo: 'Mới',
  processing: 'Đang thực hiện',
  approved: 'Chờ phê duyệt',
  completed: 'Hoàn thành',
};
const STATUS_COLORS: Record<string, string> = {
  todo: '#00A3FF',
  processing: '#EF5DA8',
  approved: '#A855F7',
  completed: '#22C55E',
};

const fixedStatusList = ['todo', 'processing', 'approved', 'completed'];
const ListTable: React.FC<Props> = ({tableDataGroup}) => {
  const [expandedStatuses, setExpandedStatuses] = useState<
    Record<string, boolean>
  >({
    todo: true,
    processing: true,
    approved: true,
    completed: true,
  });
  const toggleStatus = (key: string) => {
    setExpandedStatuses(prev => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  return (
    <View>
      {fixedStatusList.map(status => {
        const found = tableDataGroup.find(t => t.status === status);

        const tableData = found?.tableData || [];

        return (
          <View key={status} style={{marginBottom: 32}}>
            <View
              style={styles.tableCtn}>
              <TouchableOpacity
                onPress={() => toggleStatus(status)}
                style={[
                  styles.groupToggle,
                  {backgroundColor: STATUS_COLORS[status]},
                ]}>
                {expandedStatuses[status] ? (
                  <DownAngle height={16} width={16} fill={'white'} />
                ) : (
                  <RightAngle height={16} width={16} fill={'white'} />
                )}
              </TouchableOpacity>

              <View
                style={[
                  styles.groupName,
                  {backgroundColor: STATUS_COLORS[status]},
                ]}>
                <TextCM style={styles.groupNameText}>{STATUS_NAMES[status]}</TextCM>
              </View>
              <TextCM style={{fontFamily: Font.InterRegular400}}>
                {tableData.length} Công việc
              </TextCM>
            </View>
            {expandedStatuses[status] && tableData.length > 0 && (
              <TableCM
                stickyLeft={true}
                stickyColumnLeftIndex={1}
                styleTextHeader={{color: 'white'}}
                styleHeader={{backgroundColor: STATUS_COLORS[status]}}
                tableHeaders={[
                  'HM.board.table-order',
                  'HM.board.table-name',
                  'HM.board.table-tag',
                  'HM.board.table-created-date',
                  'HM.board.table-start-date',
                  'HM.board.table-due-date',
                  'HM.board.table-overdue',
                  'HM.board.table-assignee',
                  'HM.board.table-subtask',
                  'HM.board.table-action',
                ]}
                tableData={tableData}
                // useOnLayout={true}
              />
            )}
          </View>
        );
      })}
    </View>
  );
};

export default ListTable;
